import {
  ConnectedKernelListFragment$data,
  ConnectedKernelListFragment$key,
} from '../../__generated__/ConnectedKernelListFragment.graphql';
import { ContainerLogModalFragment$key } from '../../__generated__/ContainerLogModalFragment.graphql';
// import BAIPropertyFilter from '../BAIPropertyFilter';
import { isNotYetAllocatedSession } from '../../helper/sessionResourceGridData';
import ContainerLogModal from './ContainerLogModalLazy';
import { Badge } from '@lablup/ui-common/Badge';
import { IconButton } from '@lablup/ui-common/IconButton';
import { Text } from '@lablup/ui-common/Text';
import {
  badgeVariantForStatus,
  filterOutEmpty,
  filterOutNullAndUndefined,
  BAITable,
  BAIUnmountAfterClose,
  BAIDoubleBadge,
  BAIFlex,
  BAIId,
  type BAIColumnType,
  BAIText,
} from 'backend.ai-ui';
import * as _ from 'lodash-es';
import { ScrollTextIcon } from 'lucide-react';
import { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { graphql, useFragment } from 'react-relay';

type Kernel = NonNullable<ConnectedKernelListFragment$data[number]>;

interface ConnectedKernelListProps {
  kernelsFrgmt: ConnectedKernelListFragment$key;
  sessionFrgmtForLogModal: ContainerLogModalFragment$key;
  // fetchKey?: string;
  // get the project id of the session for <= v24.12.0.
  // projectId?: string | null;
}

const ConnectedKernelList: React.FC<ConnectedKernelListProps> = ({
  kernelsFrgmt,
  sessionFrgmtForLogModal,
}) => {
  const { t } = useTranslation();
  const [kernelIdForLogModal, setKernelIdForLogModal] = useState<string>();

  const kernelNodes = useFragment(
    graphql`
      fragment ConnectedKernelListFragment on KernelNode @relay(plural: true) {
        id
        row_id
        cluster_hostname
        cluster_idx
        cluster_role
        status
        status_info
        agent_id
        container_id
      }
    `,
    kernelsFrgmt,
  );

  const columns = filterOutEmpty<BAIColumnType<Kernel>>([
    {
      title: t('kernel.Hostname'),
      dataIndex: 'cluster_hostname',
      render: (hostname, record) => {
        return (
          <BAIFlex gap="xxs">
            <Text>{hostname}</Text>
            <IconButton
              variant="ghost"
              size="sm"
              icon={<ScrollTextIcon />}
              isDisabled={isNotYetAllocatedSession(record.status ?? '')}
              label={t('session.SeeContainerLogs')}
              tooltip={t('session.SeeContainerLogs')}
              onClick={() => {
                record.row_id && setKernelIdForLogModal(record.row_id);
              }}
            />
          </BAIFlex>
        );
      },
    },
    {
      title: t('kernel.Status'),
      dataIndex: 'status',
      render: (status, record) => {
        return (
          <>
            {record?.status_info !== '' ? (
              <BAIDoubleBadge
                values={[
                  {
                    label: status,
                    variant: badgeVariantForStatus('kernel', status),
                  },
                  {
                    label: record?.status_info ?? '',
                    variant: badgeVariantForStatus(
                      'kernel',
                      record?.status_info,
                    ),
                  },
                ]}
              />
            ) : (
              <Badge
                variant={badgeVariantForStatus('kernel', status)}
                label={status}
              />
            )}
          </>
        );
      },
    },
    {
      title: t('kernel.AgentId'),
      dataIndex: 'agent_id',
      render: (id) => (_.isEmpty(id) ? '-' : <BAIText copyable>{id}</BAIText>),
    },
    {
      title: t('kernel.KernelId'),
      fixed: 'left',
      dataIndex: 'row_id',
      render: (row_id) => (_.isEmpty(row_id) ? '-' : <BAIId uuid={row_id} />),
    },
    {
      title: t('kernel.ContainerId'),
      dataIndex: 'container_id',
      render: (id) => (_.isEmpty(id) ? '-' : <BAIId uuid={id} />),
    },
  ]);

  const sortedKernels = useMemo(() => {
    return _.orderBy(filterOutNullAndUndefined(kernelNodes), [
      'cluster_role',
      'cluster_idx',
    ] as Array<keyof Kernel>);
  }, [kernelNodes]);
  return (
    <>
      {/* TODO: implement filter when compute_session_node query supports filter */}
      {/* <BAIPropertyFilter
        filterProperties={[
          {
            key: 'agent_id',
            propertyLabel: t('kernel.AgentId'),
            type: 'string',
          },
        ]}
        value={filterString}
        onChange={(value) => {
          startFilterTransition(() => {
            setFilterString(value);
          });
        }}
      /> */}
      <BAITable
        scroll={{ x: 'max-content' }}
        bordered
        // loading={isPendingFilter}
        rowKey="id"
        columns={columns}
        dataSource={sortedKernels} // TODO: implement pagination when compute_session_node query supports pagination
      />

      <BAIUnmountAfterClose>
        <ContainerLogModal
          open={!!kernelIdForLogModal}
          sessionFrgmt={sessionFrgmtForLogModal || null}
          defaultKernelId={kernelIdForLogModal}
          onCancel={() => {
            setKernelIdForLogModal(undefined);
          }}
        />
      </BAIUnmountAfterClose>
    </>
  );
};

export default ConnectedKernelList;
